      p.life = 1.5 + rng();
    })
  .emitter("mist", { x: 200, y: 150, maxRate: 20 })
    .rate((t, live) => (live < 50 && counters.burnedOut < 1000 ? 20 : 0))
    .spawn((p, rng) => { p.pos = p.pos + vec2(spread(rng(), 300), 0); p.size = 3; });

