const RINGS = 6;

// Build code: a block body that loops over the emitters and returns the one Program.
export default ($) => {
  const sys = particles("bubbles")
    .param("buoyancy", { value: 50, min: 0, max: 200 })
    .bounds({ width: 150, height: 150 })
    .maxParticles(80)
    .tick(1 / 20)
